import { useState } from 'react'
import { Apple, Smartphone } from 'lucide-react'
import type { PassContent } from '@/lib/walletContent'
import { useQrDataUrl } from '@/hooks/useQrDataUrl'
import { cn } from '@/lib/cn'
import { StampGlyph } from './StampGlyph'

type Platform = 'ios' | 'android'

function Qr() {
  // The QR is auto-generated by the system and not editable by the business (§4.3).
  const url = useQrDataUrl('BNC-PREVIEW', 160)
  return (
    <div className="mx-auto mt-4 w-28 rounded-lg bg-white p-2">
      {url ? <img src={url} alt="Pass QR code (generated by the system)" className="size-full" /> : <div className="aspect-square" />}
    </div>
  )
}

function Fields({ content }: { content: PassContent }) {
  return (
    <>
      {content.primary && (
        <div className="mt-3">
          <p className="text-[10px] tracking-wide uppercase opacity-70">{content.primary.label}</p>
          <p className="flex items-center gap-2 text-lg leading-tight font-semibold">
            {content.tierBadge && <img src={content.tierBadge} alt="Tier badge" className="size-6 rounded object-cover" />}
            {content.primary.value}
          </p>
        </div>
      )}
      {content.stampGrid && (
        <div className="mt-3 grid grid-cols-5 gap-1.5" aria-label={`${content.stampGrid.filled} of ${content.stampGrid.total} stamps`}>
          {Array.from({ length: content.stampGrid.total }, (_, i) => (
            <span
              key={i}
              className={cn('flex aspect-square items-center justify-center rounded-full border', i < content.stampGrid!.filled ? 'border-transparent bg-white/90 text-black' : 'border-current/40 opacity-50')}
            >
              <StampGlyph icon={content.stampGrid!.icon} className="size-3.5" />
            </span>
          ))}
        </div>
      )}
      {content.progress && (
        <div className="mt-3">
          <div className="h-1.5 overflow-hidden rounded-full bg-white/25">
            <div className="h-full rounded-full bg-[#1747F8]" style={{ width: `${Math.min(100, (content.progress.value / Math.max(1, content.progress.max)) * 100)}%` }} />
          </div>
        </div>
      )}
      {content.secondary.length > 0 && (
        <div className="mt-3 flex flex-wrap gap-x-5 gap-y-2">
          {content.secondary.map((f) => (
            <div key={f.label}>
              <p className="text-[10px] tracking-wide uppercase opacity-70">{f.label}</p>
              <p className="text-sm font-medium">{f.value}</p>
            </div>
          ))}
        </div>
      )}
      {content.redeemed && <p className="mt-3 inline-block rounded bg-white/90 px-2 py-0.5 text-xs font-bold text-black">REDEEMED</p>}
    </>
  )
}

/**
 * Live wallet mockup: "this is how it will look on iPhone / Android" (spec §4.3).
 * Approximation only — real rendering is done by Apple Wallet / Google Wallet.
 */
export function WalletPassPreview({ content, label = 'Live wallet preview' }: { content: PassContent; label?: string }) {
  const [platform, setPlatform] = useState<Platform>('ios')
  const logo = content.logo ? <img src={content.logo} alt="" className="size-8 rounded object-cover" /> : <span className="flex size-8 items-center justify-center rounded bg-white/15 text-xs font-bold">{content.title.slice(0, 1)}</span>
  const hero = content.heroImage ? <img src={content.heroImage} alt="" className="h-20 w-full object-cover" /> : null

  return (
    <section aria-label={label} className="flex flex-col items-center gap-3">
      <div role="tablist" aria-label="Preview platform" className="inline-flex rounded-lg border border-line bg-surface p-0.5 text-sm">
        {(
          [
            ['ios', 'iPhone', Apple],
            ['android', 'Android', Smartphone],
          ] as const
        ).map(([value, text, Icon]) => (
          <button
            key={value}
            role="tab"
            type="button"
            aria-selected={platform === value}
            onClick={() => setPlatform(value)}
            className={cn('inline-flex items-center gap-1.5 rounded-md px-3 py-1.5', platform === value ? 'bg-accent text-on-accent' : 'text-muted hover:text-fg')}
          >
            <Icon className="size-3.5" aria-hidden /> {text}
          </button>
        ))}
      </div>

      {/* Device frame */}
      <div className={cn('w-[290px] rounded-[2.2rem] border-[10px] border-neutral-900 bg-neutral-900 shadow-card', platform === 'android' && 'rounded-[1.6rem]')}>
        <div className={cn('min-h-[480px] overflow-hidden bg-neutral-100 p-3', platform === 'ios' ? 'rounded-[1.6rem]' : 'rounded-[1rem]')}>
          <div className="overflow-hidden rounded-2xl shadow-lg" style={{ background: content.background, color: content.textColor }} data-testid="wallet-pass">
            {platform === 'ios' ? (
              <>
                <div className="flex items-center justify-between gap-2 px-4 pt-4">
                  {logo}
                  <p className="truncate text-sm font-semibold">{content.title}</p>
                </div>
                {hero && <div className="mt-3">{hero}</div>}
                <div className="px-4 pb-4">
                  <Fields content={content} />
                  <Qr />
                </div>
              </>
            ) : (
              <>
                <div className="flex items-center gap-2 px-4 pt-4">
                  {logo}
                  <p className="truncate text-xs opacity-80">{content.title}</p>
                </div>
                <div className="px-4 pb-4">
                  <p className="mt-3 text-xl font-semibold">{content.title}</p>
                  <Fields content={content} />
                  <Qr />
                </div>
                {hero}
              </>
            )}
          </div>
          <p className="mt-3 text-center text-[11px] text-neutral-500">
            {content.templateName} · {platform === 'ios' ? 'Apple Wallet' : 'Google Wallet'} (approximate)
          </p>
        </div>
      </div>
    </section>
  )
}
